package com.graduation.lab.domain;import com.graduation.lab.auth.AuthService;import com.graduation.lab.common.ApiException;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController@RequestMapping("/api/reservations")public class LabReservationController{private final LabReservationRepository repo;private final LaboratoryRepository labs;private final AuthService auth;public LabReservationController(LabReservationRepository r,LaboratoryRepository l,AuthService a){repo=r;labs=l;auth=a;}public record Create(@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Positive Long labId,@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=255) String title,@jakarta.validation.constraints.Size(max=1000) String purpose,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Future LocalDateTime startTime,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.Future LocalDateTime endTime){}@PostMapping @Transactional public LabReservation create(@jakarta.validation.Valid @RequestBody Create x){labs.findLockedById(x.labId()).filter(l->"OPEN".equals(l.getStatus())).orElseThrow(()->ApiException.notFound("实验室不存在或未开放"));if(x.startTime()==null||x.endTime()==null||!x.endTime().isAfter(x.startTime())||x.startTime().isBefore(LocalDateTime.now()))throw ApiException.badRequest("预约时间无效");if(!repo.conflicts(x.labId(),x.startTime(),x.endTime()).isEmpty())throw ApiException.badRequest("该时间段已被占用");var r=new LabReservation();r.setLabId(x.labId());r.setUserId(auth.currentUser().getId());r.setTitle(x.title());r.setPurpose(x.purpose());r.setStartTime(x.startTime());r.setEndTime(x.endTime());r.setStatus("PENDING");return repo.save(r);}@GetMapping public List<LabReservation>list(){var u=auth.currentUser();return "ADMIN".equals(u.getRole())?repo.findAll(org.springframework.data.domain.PageRequest.of(0,200,org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"id"))).getContent():repo.findTop200ByUserIdOrderByStartTimeDesc(u.getId());}@PatchMapping("/{id}/status")@PreAuthorize("hasRole('ADMIN')")public LabReservation status(@PathVariable Long id,@RequestParam String value){if(!List.of("APPROVED","REJECTED","CANCELLED").contains(value))throw ApiException.badRequest("状态非法");var r=repo.findById(id).orElseThrow(()->ApiException.notFound("预约不存在"));r.setStatus(value);return repo.save(r);}}
